class SafePlacementRule:
    name = "safe_placement"
    priority = 100

    def allowed(self, partial, memory, candidates):
        if not candidates:
            return []
        return list(candidates)

    def score(self, partial, memory, action):
        so, sd = action.so, action.sd
        c = partial.g(so)

        dest_empty = partial.h(sd) == 0
        compatible = dest_empty or partial.g(sd) >= c

        trial = partial.copy(track=False)
        trial.move(so, sd)

        return (
            trial.bad(),
            0 if compatible else 1,
            0 if partial.is_sorted_stack(sd) else 1,
            0 if not partial.is_sorted_stack(so) else 1,
            trial.ub(sd),
            trial.h(sd),
            so,
            sd,
        )


class SafePlacementConstructionMachine:
    def __init__(self, problem, rules):
        self.problem = problem
        self.rules = list(rules)
        self.finite = True

    def allowed(self, partial, memory, candidates):
        if not self.rules:
            return list(candidates)
        return self.rules[0].allowed(partial, memory, candidates)

    def score(self, partial, memory, action):
        if not self.rules:
            return ()
        return self.rules[0].score(partial, memory, action)


def build_component(problem, **params):
    return SafePlacementConstructionMachine(problem, [SafePlacementRule()])
